      if not ok then
        failed("before", err)
      end
    end
    local results
    if parts.around ~= nil then
      results = table.pack(parts.around(previous, ...))
    else
      results = table.pack(previous(...))
    end
    if parts.after ~= nil then
      local ok, err = pcall(parts.after, ...)
      if not ok then
        failed("after", err)
      end
    end
    return table.unpack(results, 1, results.n)
  end)
end
