  MARK = 351630468, SPR = 4051701020, ATLAS = "#/menu/220_img/bbd_md/bbd_md.g4tx",
  NUMBER = 4219493944,
  N = 40,                    -- instances of the mark and number layers
  DX = 30, DY = -30, SIZE = 40, Q = 36, NODE_QUAD = 1909474081, MESH_QUAD = 312193881,
